    top_module dut (
        .CLK(CLK),
        .DOWN(DOWN),
        .LOAD(LOAD),
        .UP(UP),
        .Q(Q)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            LOAD = 1;
            UP = 0;
            DOWN = 0;
            @(posedge CLK);
            #1 LOAD = 0;
        end
        endtask
    task testcase001;

        begin
            test_num = 1;
            $display("Testcase %03d: Reset/Load verification", test_num);
            reset_dut();

            @(posedge CLK);
            #1 #1;
 check_outputs(4'h0);
        end
        endtask

    task testcase002;

        begin
            test_num = 2;
            $display("Testcase %03d: Increment check (0 to 5)", test_num);
            reset_dut();
            UP = 1;
            DOWN = 0;
            repeat(5) @(posedge CLK);
            #1 UP = 0;
            #1;

            check_outputs(4'h5);
        end
        endtask

    task testcase003;

        begin
            test_num = 3;
            $display("Testcase %03d: Decrement check (Reset to 0, count down to 14)", test_num);
            reset_dut();
            UP = 0;
            DOWN = 1;
            repeat(2) @(posedge CLK);
            #1 DOWN = 0;
            #1;

            check_outputs(4'hE);
        end
