        begin
            test_num = 5;
            $display("Testcase %03d: Upward wraparound (15 to 0)", test_num);
            reset_dut();
            UP = 1;
            repeat(16) @(posedge CLK);
            #1 UP = 0;
            #1;

            check_outputs(4'h0);
        end
        endtask

