    input  VPWR, VGND;
    output VPB, VNB;

    // Local signals
    wire pgood_out;

    //                                 Name         Output             Other arguments
    or                                 or0         (pgood_out        , A2, A1                );
    or                                 or1         (pgood_out        , B2, B1                );
    buf                                buf0        (VPB              , pgood_out            );
    not                                not0        (pgood_out        , pgood_out            );
